import{_ as e,c as r,o as i,ah as h}from"./chunks/framework.Dnh4IO1K.js";const _=JSON.parse('{"title":"第十八卦 蛊 山风蛊 艮上巽下","description":"周易 - 第十八卦 蛊 山风蛊 艮上巽下","frontmatter":{"title":"第十八卦 蛊 山风蛊 艮上巽下","description":"周易 - 第十八卦 蛊 山风蛊 艮上巽下"},"headers":[],"relativePath":"zh/classics/zhouyi/019.md","filePath":"zh/classics/zhouyi/019.md"}'),l={name:"zh/classics/zhouyi/019.md"};function t(n,a,s,d,o,c){return i(),r("div",null,[...a[0]||(a[0]=[h('<h1 id="蛊" tabindex="-1">蛊 <a class="header-anchor" href="#蛊" aria-label="Permalink to “蛊”">​</a></h1><h2 id="卦辞" tabindex="-1">卦辞 <a class="header-anchor" href="#卦辞" aria-label="Permalink to “卦辞”">​</a></h2><p>元亨，利涉大川。先甲三日，后甲三日。</p><h3 id="彖传" tabindex="-1">彖传 <a class="header-anchor" href="#彖传" aria-label="Permalink to “彖传”">​</a></h3><p>蛊，刚上而柔下，巽而止，蛊。蛊，元亨，而天下治也。利涉大川，往有事也。先甲三日，后甲三日，终则有始，天行也。</p><h3 id="象传" tabindex="-1">象传 <a class="header-anchor" href="#象传" aria-label="Permalink to “象传”">​</a></h3><p>山下有风，蛊；君子以振民育德。</p><h3 id="初六" tabindex="-1">初六 <a class="header-anchor" href="#初六" aria-label="Permalink to “初六”">​</a></h3><p>干父之蛊，有子，考无咎，厉终吉。象 曰：干父之蛊，意承考也。</p><h3 id="九二" tabindex="-1">九二 <a class="header-anchor" href="#九二" aria-label="Permalink to “九二”">​</a></h3><p>干母之蛊，不可贞。象曰：干母之蛊，得中道也。</p><h3 id="九三" tabindex="-1">九三 <a class="header-anchor" href="#九三" aria-label="Permalink to “九三”">​</a></h3><p>干父小有晦，无大咎。象曰：干父之蛊，终无咎也。</p><h3 id="六四" tabindex="-1">六四 <a class="header-anchor" href="#六四" aria-label="Permalink to “六四”">​</a></h3><p>裕父之蛊，往见吝。象曰：裕父之蛊，往未得也。</p><h3 id="六五" tabindex="-1">六五 <a class="header-anchor" href="#六五" aria-label="Permalink to “六五”">​</a></h3><p>干父之蛊，用誉。象曰：干父之蛊；承以德也。</p><h3 id="上九" tabindex="-1">上九 <a class="header-anchor" href="#上九" aria-label="Permalink to “上九”">​</a></h3><p>不事王侯，高尚其事。象曰：不事王侯，志可则也。</p>',19)])])}const b=e(l,[["render",t]]);export{_ as __pageData,b as default};
